package hello

import (
  "context"
  "hatamoto.dev/sdk"
)

func init() { sdk.Register(&Plugin{}) }

type Plugin struct{ deps sdk.Deps }

func (p *Plugin) Manifest() sdk.Manifest {
  return sdk.Manifest{
    Name: "hello", Version: "0.1.0", SDK: "^0.1",
  }
}

func (p *Plugin) Wire(d sdk.Deps) error {
  p.deps = d
  sdk.OnAction(d.Hooks, sdk.EntityPublished, 10,
    func(ctx context.Context, e sdk.EntityEvent) {
      d.Logger.Info("published", "id", e.ID)
    })
  return nil
}
